sys_script_client.script:
function onSubmit() {
    //Type appropriate comment here, and begin script below
    var baseId = g_form.getValue("base");
    var gaBaseTable = new GlideAjax('BaseTableUtils');
    gaBaseTable.addParam('sysparm_name', 'checkVacancies');
    gaBaseTable.addParam('sysparm_baseid', baseId);
	gaBaseTable.getXMLAnswer(function(answer) {
            if (answer === 'false') {
                return true;
            } else {
				g_form.showFieldMsg("base", "There is no spots left for this base.", "error");
            }
        });
		g_form.addInfoMessage(baseId);
		return false;
}
